function itemSpans(lines) {
  const spans = [];
  for (let i = 0; i < lines.length; i++) {
    const m = /^- id:\s*(\S+)\s*$/.exec(lines[i]);
    if (!m) continue;
    let end = i;
    for (let j = i + 1; j < lines.length && !/^\S/.test(lines[j]); j++) {
