export function bankFingerprint(factsDir, gapTagsPath) {
  const { facts } = readFacts(factsDir);
  return createHash("sha1")
    .update(JSON.stringify(facts.map(({ index, file, ...f }) => f)))
    .update(JSON.stringify(readGaps(gapTagsPath)))
    .digest("hex")
    .slice(0, 12);
}

